"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["12713"],{84882(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.formatos_permitidos.tamanho_maximo_bytes_max_invalido","status":422,"titulo":"O tamanho m\xe1ximo em bytes por formato, quando presente, deve ser maior que zero"},"descricao":{"codigo":"uniplus.selecao.formatos_permitidos.tamanho_maximo_bytes_max_invalido","requisitos":[],"oQueAconteceu":["Cada formato da lista de formatos permitidos pode ter um limite de tamanho pr\xf3prio,\\n`tamanhoMaximoBytesMax`, em bytes. Quando o limite \xe9 informado, ele precisa ser maior que zero, e\\na entrada trouxe zero ou um n\xfamero negativo. Um valor que n\xe3o seja n\xfamero inteiro \xe9 outra recusa\\n([`forma_invalida`](/erros/uniplus.selecao.formatos_permitidos.forma_invalida)).","Este limite \xe9 independente do limite geral da exig\xeancia, `tamanhoMaximoBytes`, cuja recusa \xe9 outra\\n([`tamanho_maximo_bytes_invalido`](/erros/uniplus.selecao.documento_exigido.tamanho_maximo_bytes_invalido)).","A confer\xeancia acontece na montagem de cada exig\xeancia, depois das confer\xeancias do tipo de\\ndocumento, das condi\xe7\xf5es e das bases legais, e depois da idade m\xe1xima de emiss\xe3o; a do modelo\\ncitado vem em seguida. A confer\xeancia registra as recusas das regras informadas, e a lista de\\nformatos para na primeira entrada com defeito. Em cada entrada, o limite \xe9 a \xfaltima confer\xeancia,\\ndepois do formato reconhecido\\n([`formato_invalido`](/erros/uniplus.selecao.formatos_permitidos.formato_invalido)) e da repeti\xe7\xe3o\\n([`formato_duplicado`](/erros/uniplus.selecao.formatos_permitidos.formato_duplicado)).","Esta mesma confer\xeancia \xe9 refeita quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada: em toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios,\\nas opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho da p\xe1gina).\\nPelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz limite n\xe3o positivo, porque a\\ndefini\xe7\xe3o o recusa antes. Nessas leituras a recusa se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido\\nenviado."],"comoResolver":["Informe `tamanhoMaximoBytesMax` como um n\xfamero inteiro de bytes maior que zero, ou omita o campo\\n(ou envie nulo) para o formato n\xe3o ter limite pr\xf3prio. Depois, envie a defini\xe7\xe3o de novo.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema\\nrecusou a configura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir os documentos exigidos do\\nprocesso n\xe3o a corrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Consulta do formul\xe1rio renderiz\xe1vel do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, submiss\xe3o, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Formatos permitidos"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);